/* The client renders server snapshots; it owns no multiplayer money or cargo rules. */
(()=>{
 if(typeof window==='undefined'||typeof location==='undefined')return;
 const API=/^(localhost|127\.0\.0\.1)$/.test(location.hostname)?location.origin:'https://zhouzhou-auction-rooms.fresh-eagle-4882.chatgpt.site';
 const SESSION='zhouzhou-online-session-v1',PROFILES='zhouzhou-online-profiles-v1';
 const modes={shape:'轮廓扫描',grade:'品质扫描',mixed:'混合扫描',category:'分类线索'};
 let session=null,state=null,error='',polling=false,sending=false,signature='',clockOffset=0,priceReminder='',rankBy='balance',dragging=false,bidDraft={key:'',value:''};
 try{session=JSON.parse(sessionStorage.getItem(SESSION)||'null');}catch{}
 const esc=value=>escapeHTML(String(value??'')),moneyText=n=>money(n||0),me=()=>state?.players.find(p=>p.id===state.myId),host=()=>state?.hostId===state?.myId;
 const name=id=>state?.players.find(p=>p.id===id)?.nickname||'玩家';
 function profiles(){try{return JSON.parse(localStorage.getItem(PROFILES)||'[]');}catch{return [];}}
 function saveSession(value){session=value;sessionStorage.setItem(SESSION,JSON.stringify(value));const all=profiles().filter(p=>!(p.code===value.code&&p.nickname===value.nickname));all.unshift(value);localStorage.setItem(PROFILES,JSON.stringify(all.slice(0,6)));}
 function apply(next){if(state&&next.code===state.code&&(next.revision||0)<(state.revision||0))return;state=next;clockOffset=Date.now()-next.serverNow;error='';if(s.view==='online')render();}
 async function post(path,data,token=session?.token){const response=await fetch(API+'/api/'+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(data),signal:AbortSignal.timeout(10000)});let result;try{result=await response.json();}catch{throw Error('联机服务暂不可用，请稍后重试。');}if(result.state&&(!token||session?.token===token))apply(result.state);if(!response.ok)throw Object.assign(Error(result.error||'联机请求失败。'),{status:response.status});return result;}
 async function send(type,data={},quiet=false){if(!session)return;const payload={type,requestId:crypto.randomUUID(),boxNo:state?.boxNo,round:state?.auctionRound,duelPrice:state?.duel?.price,...data};try{if(!quiet){sending=true;updateControls();}let result;try{result=await post('rooms/'+session.code+'/action',payload);}catch(e){if(e instanceof TypeError)result=await post('rooms/'+session.code+'/action',payload);else throw e;}return result;}catch(e){error=e.name==='TimeoutError'?'网络连接较慢，正在重新同步。':e.message;if(s.view==='online')showError();}finally{if(!quiet){sending=false;updateControls();}}}
 function forgetSession(closed){if(!closed||session?.token!==closed.token)return;session=null;state=null;signature='';sessionStorage.removeItem(SESSION);localStorage.setItem(PROFILES,JSON.stringify(profiles().filter(p=>p.token!==closed.token)));}
 async function poll(){if(!session||polling)return;polling=true;const current=session;try{await post('rooms/'+current.code+'/state',{});}catch(e){if(session?.token!==current.token)return;if([401,404,410].includes(e.status)){forgetSession(current);error=e.status===401?'本局身份已失效，请重新加入房间。':'房间已经关闭，请创建或加入新房间。';if(s.view==='online')render();}else{error='连接中断，正在等待重连：'+e.message;if(s.view==='online')showError();}}finally{polling=false;}}
 function showError(){const el=document.getElementById('onlineError');if(el){el.textContent=error;el.hidden=!error;}}
 function updateControls(){document.querySelectorAll('#onlineBidForm button,#onlineDuel button').forEach(b=>{if(sending)b.disabled=true;else if(b.dataset.duelStep)b.disabled=!state||state.pause||state.duel?.turn!==state.myId||state.duel.price+Number(b.dataset.duelStep)>me().balance;else if(state?.stage==='bidding')b.disabled=!!state.pause||!state.active.includes(state.myId)||state.bids[state.myId]!==undefined;else b.disabled=!!state?.pause;});}
 function open(){s.view='online';renderGrid();if(session&&!state)poll();}
 function dialogs(){if(document.getElementById('onlineConnectDialog'))return;document.body.insertAdjacentHTML('beforeend',`
 <dialog id="onlineConnectDialog"><form id="onlineConnectForm"><div class="eyebrow">FRIENDS / 联机房间</div><h2 id="onlineConnectTitle">创建房间</h2><label>本局昵称<input name="nickname" autocomplete="nickname" maxlength="16" required placeholder="朋友们怎么称呼你"></label><div id="onlineJoinFields"><label>4位房间号<input name="code" inputmode="numeric" maxlength="4" pattern="[1-9][0-9]{3}" placeholder="例如 1234"></label></div><div id="onlineCreateFields"><label>箱子起拍价（万）<input name="price" type="number" min="100" max="5000" step="0.01" value="100" required></label><label>战局箱数（1–50）<input name="rounds" type="number" min="1" max="50" step="1" value="10" required></label><p>2–6人 · 每人5000万独立资金 · 每箱24件全库等概率货物</p></div><p id="onlineConnectError" class="negative" role="alert"></p><div class="actions"><button type="button" class="secondary" data-online-close="onlineConnectDialog">取消</button><button type="submit" id="onlineConnectSubmit">创建房间</button></div></form></dialog>
 <dialog id="onlinePriceDialog"><form id="onlinePriceForm"><h2>下一箱起拍价</h2><p>起拍价只决定报价下限，不影响货物、件数或扫描模式。</p><label>金额（万）<input id="onlineNextPrice" type="number" min="100" max="5000" step="0.01" required></label><div class="actions"><button type="button" class="secondary" data-online-close="onlinePriceDialog">沿用原金额</button><button type="submit">保存金额</button></div></form></dialog>
 <dialog id="onlineConfirmDialog"><h2 id="onlineConfirmTitle">确认结束战局？</h2><p id="onlineConfirmDetails"></p><div class="actions"><button type="button" class="secondary" data-online-close="onlineConfirmDialog">取消</button><button type="button" id="onlineConfirmAction">确认</button></div></dialog>`);}
 function connectDialog(kind){dialogs();const form=document.getElementById('onlineConnectForm');form.dataset.kind=kind;document.getElementById('onlineConnectTitle').textContent=kind==='create'?'创建联机房间':'加入朋友的房间';document.getElementById('onlineConnectSubmit').textContent=kind==='create'?'创建房间':'加入房间';document.getElementById('onlineJoinFields').hidden=kind==='create';document.getElementById('onlineCreateFields').hidden=kind==='join';form.elements.code.disabled=kind==='create';form.elements.code.required=kind==='join';form.elements.price.disabled=form.elements.rounds.disabled=kind==='join';document.getElementById('onlineConnectError').textContent='';document.getElementById('onlineConnectDialog').showModal();}
 function confirm(kind){dialogs();document.getElementById('onlineConfirmAction').dataset.kind=kind;document.getElementById('onlineConfirmTitle').textContent=kind==='leave'?'离开当前房间？':kind==='vote'?'投票结束战局？':'结束本战局并结算？';document.getElementById('onlineConfirmDetails').textContent=kind==='leave'?'本局身份和资金会保留，可从此浏览器重连。房主离线时整局暂停，1分钟后在线玩家可投票。':kind==='vote'?'你将投票选择结束；超过半数在线玩家同意后生效。':'已成交但未刮完的箱子将自动揭晓并出售；未成交的报价全部解除占款。之后生成最终排行榜。';document.getElementById('onlineConfirmDialog').showModal();}
 function priceDialog(){dialogs();document.getElementById('onlineNextPrice').value=state.settings.price/10000;document.getElementById('onlinePriceDialog').showModal();}
 function landing(){const recent=profiles();return `<section class="online-landing"><div class="eyebrow">MULTIPLAYER / FRIENDS</div><h1>朋友组局，轮廓竞拍。</h1><p>输入昵称与房间号，一起看轮廓、猜价值、争一箱未知。</p><div class="online-feature-row"><span>2–6人</span><span>每人5000万</span><span>每箱24件</span><span>5轮同时报价</span></div><div class="actions"><button data-online-create>创建房间</button><button class="secondary" data-online-join>加入房间</button></div><div class="online-how"><h2>从轮廓里读出价值</h2><p>相邻货物合成整体轮廓。每轮开始扫描3件货物或透露一类件数，最多扫描4轮；报价提交后立即公开。每轮60秒，全员完成后提前结算。</p><p>四轮提前成交差距：30% / 25% / 20% / 10%。第五轮最高价成交，同价进入轮流加价对决。赢家刮箱，朋友围观，整箱自动出售。</p><p>联机资金与单人存档独立，无贷款或止损。金额、货物和成交由服务端校验。</p></div>${recent.length?`<h2>继续本机战局</h2><div class="online-recent">${recent.map((p,i)=>`<button class="secondary" data-online-resume="${i}">房间 ${esc(p.code)} · ${esc(p.nickname)}</button>`).join('')}</div>`:''}</section>`;}
 function playerCards(){return `<div class="online-players">${state.players.map(p=>`<article class="online-player ${p.id===state.myId?'is-me':''}"><div><strong>${esc(p.nickname)}</strong><span class="online-status ${p.online?'is-online':''}">${p.online?'在线':'离线'}${p.id===state.hostId?' · 房主':''}${p.id===state.myId?' · 你':''}</span></div><span>可用 <b>${moneyText(p.available)}</b></span>${p.reserved?`<small>本轮占款 ${moneyText(p.reserved)}</small>`:''}<small>拍得 ${p.wins} 箱 · 净利润 <b class="${p.profit>=0?'positive':'negative'}">${p.profit>=0?'+':''}${moneyText(p.profit)}</b></small></article>`).join('')}</div>`;}
 function toolbar(){return `<div class="online-room-head"><div><div class="eyebrow">FRIENDS / 房间号</div><h1>${esc(state.code)}</h1><p>${state.stage==='lobby'?'等待朋友入场':state.stage==='ended'?'本战局已结束':`第 ${state.boxNo} / ${state.settings.rounds} 箱`} · 起拍 ${moneyText(state.settings.price)}</p></div><div class="actions"><button class="secondary" data-online-leave>离开房间</button>${host()&&state.stage!=='ended'?'<button class="secondary online-danger" data-online-end>结束本战局并结算</button>':''}</div></div>${host()?`<label class="online-check"><input id="onlineNoReminder" type="checkbox" ${state.settings.noReminder?'checked':''}>不再提醒是否更改箱子金额</label>`:''}`;}
 function pausePanel(){if(!state.pause)return '';const eligible=state.players.filter(p=>p.online),counts={continue:0,end:0};for(const p of eligible)if(state.pause.votes[p.id])counts[state.pause.votes[p.id]]++;return `<section class="online-pause" role="status"><h2>房主已断线，战局暂停</h2><p>报价、刮箱和倒计时已暂停，资金与进度保留。<span id="onlineHostWait"></span></p>${state.pause.voteReady?`<p>请全体在线玩家投票，超过半数生效；平票继续等待，可修改投票。</p><div class="actions"><button data-online-vote="continue">随机更换房主并继续（${counts.continue}票）</button><button class="secondary" data-online-vote="end">结束并结算（${counts.end}票）</button></div><small>你的选择：${state.pause.votes[state.myId]==='continue'?'继续':state.pause.votes[state.myId]==='end'?'结束':'尚未投票'}</small>`:''}</section>`;}
 function silhouette(){const lot=state.lot,w=lot.w,h=lot.h,mask=lot.occupancy;let fills='',edges='',grid='';for(let x=0;x<=w;x++)grid+=`M${x},0V${h}`;for(let y=0;y<=h;y++)grid+=`M0,${y}H${w}`;const occupied=(x,y)=>x>=0&&x<w&&y>=0&&y<h&&mask[y*w+x]==='1';for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(occupied(x,y)){fills+=`<rect x="${x}" y="${y}" width="1" height="1"/>`;if(!occupied(x,y-1))edges+=`M${x},${y}h1`;if(!occupied(x,y+1))edges+=`M${x},${y+1}h1`;if(!occupied(x-1,y))edges+=`M${x},${y}v1`;if(!occupied(x+1,y))edges+=`M${x+1},${y}v1`;}
 const clues=lot.clues.filter(c=>c.kind!=='category').map(c=>c.kind==='shape'?`<rect class="online-shape-clue" x="${c.x}" y="${c.y}" width="${c.w}" height="${c.h}"><title>第${c.round}轮轮廓线索</title></rect>`:`<rect x="${c.x}" y="${c.y}" width="1" height="1" fill="${grades[c.grade].color}" stroke="#ffffff" stroke-width=".06"><title>第${c.round}轮品质线索，仅表示品质</title></rect>`).join('');return `<svg class="online-silhouette" viewBox="-.6 -.6 ${w+1.2} ${h+1.2}" role="img" aria-label="本箱24件货物的合并轮廓、完整1乘1背景网格与已公开扫描线索"><g fill="#657681" shape-rendering="crispEdges">${fills}</g><path class="online-cell-grid" d="${grid}" fill="none" stroke="#aac6d7" stroke-opacity=".32" stroke-width=".04"/><path d="${edges}" fill="none" stroke="#c9d9e3" stroke-width=".08"/>${clues}</svg>`;}
 function cluesPanel(){const l=state.lot,cats=l.clues.filter(c=>c.kind==='category');return `<div class="online-scan-info"><strong>${modes[l.mode]}</strong><span>已公开 ${l.mode==='category'?cats.length+'类':l.clues.length+'件'}线索 · 固定24件货物</span><p>${l.mode==='category'?'分类线索显示本箱实际件数，不标记位置。':l.mode==='grade'?'彩色格子是品质提示，不表示物品只占1格。':l.mode==='mixed'?'灰色边界为真实占格，彩色1格仅表示品质。':'灰色边界表示扫描物品的真实占格，未显示品质。'}</p>${cats.map(c=>`<span class="chip">第${c.round}轮 · ${esc(c.cat)}：${c.count}件</span>`).join('')}</div>`;}
 function quoteTable(){const rounds=state.history.map(r=>({round:r.round,bids:Object.fromEntries(r.bids.map(b=>[b.id,b.amount])),current:false}));if(state.stage==='bidding')rounds.push({round:state.auctionRound,bids:state.bids,current:true});return `<section class="online-bid-history"><h3>每轮报价</h3><div class="table-wrap"><table aria-label="本箱每轮各玩家报价"><thead><tr><th>轮次</th>${state.players.map(p=>`<th>${esc(p.nickname)}${p.id===state.myId?' · 你':''}</th>`).join('')}</tr></thead><tbody>${rounds.map(r=>`<tr class="${r.current?'is-current':''}"><th>第${r.round}轮${r.current?' · 当前':''}</th>${state.players.map(p=>`<td>${r.bids[p.id]!==undefined?moneyText(r.bids[p.id]):r.current?(state.active.includes(p.id)?'等待报价':'已退出'):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><small>“—”表示该轮未报价；当前轮提交后立即公开。</small></section>`;}
 function bidPanel(){const draftKey=state.code+'-'+state.boxNo+'-'+state.auctionRound;if(bidDraft.key!==draftKey)bidDraft={key:draftKey,value:''};const p=me(),active=state.active.includes(p.id),submitted=state.bids[p.id]!==undefined,base=Math.max(state.settings.price,state.previousBids[p.id]||0),top=Math.max(0,...Object.values(state.bids));const disabled=!active||submitted||!!state.pause;return `<section class="panel online-bid-panel"><div class="eyebrow">BID / 同时报价</div><h2>第 ${state.auctionRound} / 5 轮 <span id="onlineCountdown"></span></h2><p>${state.auctionRound<=4?`最高价达到第二高价的 ${[130,125,120,110][state.auctionRound-1]}%，即可提前成交。`:'最高价成交；同价进入最终加价对决。'}</p><p>本轮已公开最高价 <strong>${moneyText(top)}</strong></p>${quoteTable()}<form id="onlineBidForm"><label>你的整箱总报价（万）<input id="onlineBidAmount" type="number" step="0.01" min="${base/10000}" max="${p.balance/10000}" value="${submitted?state.bids[p.id]/10000:esc(bidDraft.value||base/10000)}" ${disabled?'disabled':''} required></label><div class="online-quick">${[100000,500000,1000000,5000000].map(n=>`<button type="button" class="secondary" data-online-quick="${n}" ${disabled?'disabled':''}>＋${n/10000}万</button>`).join('')}</div><div class="actions"><button type="submit" ${disabled?'disabled':''}>${submitted?'本轮已报价':'提交总报价'}</button><button type="button" class="secondary" data-online-pass ${disabled?'disabled':''}>退出本箱竞拍</button></div></form><p>${!active?'你已退出本箱，下一箱可重新参加。':submitted?'报价已提交并公开，等待其他玩家。未成交会解除本轮占款。':`不得低于自己的上一轮报价 ${moneyText(state.previousBids[p.id]||0)}，可用总资金 ${moneyText(p.balance)}。`}</p></section>`;}
 function duelPanel(){const d=state.duel,p=me(),turn=d.turn===p.id;return `<section class="panel"><div class="eyebrow">FINAL DUEL / 最终对决</div><h2>${esc(name(d.turn))}加价 <span id="onlineCountdown"></span></h2><div class="auction-price">${moneyText(d.price)}</div><p>最高报价者：${d.leader?esc(name(d.leader)):'第五轮同价，尚未加价'}。轮流加价，30秒超时放弃。</p><p>你的原有余额 ${moneyText(p.balance)}，本次加价后的总价不能超过它。</p><div id="onlineDuel" class="actions">${[500000,1000000,3000000,5000000].map(n=>`<button data-duel-step="${n}" ${!turn||state.pause||d.price+n>p.balance?'disabled':''}>＋${n/10000}万</button>`).join('')}<button class="secondary" data-duel-pass ${!turn||state.pause?'disabled':''}>放弃</button></div><p>${turn?'轮到你：选择一个可负担的加价档位，或放弃。':'等待对决中的玩家操作，你可以继续观察线索。'}</p>${quoteTable()}</section>`;}
 function revealBoard(){const lot=state.lot,can=lot.winnerId===state.myId&&state.stage==='reveal'&&!state.pause;return `<div class="online-cargo-scroll"><div class="online-cargo" style="--cols:${lot.w};--rows:${lot.h}">${lot.items.map(it=>{const original=it.key?itemByKey.get(it.key):null;return `<button class="online-package ${it.revealed?'opened':''}" style="grid-column:${it.x+1}/span ${it.w};grid-row:${it.y+1}/span ${it.h};--grade:${it.revealed?grades[it.grade].color:'#7d939f'}" data-online-slot="${it.slot}" ${!can||it.revealed?'disabled':''} aria-label="${it.revealed?esc(it.name)+' '+moneyText(it.value):can?'刮开'+it.w+'乘'+it.h+'格包裹，回车可揭晓':'围观未揭晓包裹'}">${original?itemVisual(original,'stock')+'<small>'+esc(it.name)+'</small><strong>'+moneyText(it.value)+'</strong>':'<span class="online-package-base">?</span>'}${it.revealed?'':`<canvas data-online-mask="${it.slot}"></canvas>`}</button>`;}).join('')}</div></div>`;}
 function revealPanel(){const l=state.lot,found=l.items.filter(x=>x.revealed),value=found.reduce((n,it)=>n+it.value,0),can=l.winnerId===state.myId&&!state.pause;return `<section class="panel"><div class="eyebrow">UNBOX / 一起揭晓</div><h2>${esc(name(l.winnerId))}拍得本箱</h2><p>成交 ${moneyText(l.cost)} · 已揭晓 ${found.length}/24件</p><div class="auction-price">${moneyText(value)}</div><p>${can?'按住拖动刮开包裹，朋友会同步看到进度。':'围观赢家刮箱，揭晓进度实时同步。'}</p>${state.stage==='reveal'?`<button data-online-reveal-all ${!can?'disabled':''}>快速揭晓整箱</button>`:''}<p>整箱揭晓后按截图标价自动出售，收入仅进入赢家的联机账户。</p></section>`;}
 function leaderboard(){if(state.stage!=='ended')return '';const sorted=[...state.players].sort((a,b)=>b[rankBy]-a[rankBy]);return `<section class="panel online-ranking"><div class="intro"><h2>最终排行榜</h2><label>排序<select id="onlineRankBy"><option value="balance" ${rankBy==='balance'?'selected':''}>剩余金额</option><option value="wins" ${rankBy==='wins'?'selected':''}>拍得次数</option><option value="profit" ${rankBy==='profit'?'selected':''}>累计净利润</option></select></label></div><div class="table-wrap"><table><thead><tr><th>排名</th><th>昵称</th><th>剩余金额</th><th>拍得箱数</th><th>累计净利润</th></tr></thead><tbody>${sorted.map((p,i)=>`<tr><td>${i&&sorted[i-1][rankBy]===p[rankBy]?sorted.findIndex(x=>x[rankBy]===p[rankBy])+1:i+1}</td><td>${esc(p.nickname)}${p.id===state.myId?' · 你':''}</td><td>${moneyText(p.balance)}</td><td>${p.wins}</td><td class="${p.profit>=0?'positive':'negative'}">${p.profit>=0?'+':''}${moneyText(p.profit)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel online-ranking"><h2>各箱盈亏明细</h2><div class="table-wrap"><table><thead><tr><th>箱次</th><th>赢家</th><th>成交价</th><th>卖货收入</th><th>净利润</th></tr></thead><tbody>${state.settlements.map(r=>`<tr><td>第${r.boxNo}箱</td><td>${r.flow?'流拍':esc(name(r.winnerId))}</td><td>${r.flow?'—':moneyText(r.cost)}</td><td>${r.flow?'—':moneyText(r.value)}</td><td class="${r.profit>=0?'positive':'negative'}">${r.flow?'不扣款':(r.profit>=0?'+':'')+moneyText(r.profit)}</td></tr>`).join('')}</tbody></table></div></section>`;}
 function boxResult(){const r=state.settlements.at(-1);if(!r)return '';return `<section class="online-result"><div class="eyebrow">SETTLEMENT / 本箱结算</div><h2>${r.flow?'本箱流拍':esc(name(r.winnerId))+'的本箱收益'}</h2>${r.flow?'<p>本轮不扣款，计入战局总轮数。</p>':`<div class="stats"><div class="stat"><small>成交价</small><strong>${moneyText(r.cost)}</strong></div><div class="stat"><small>出售收入</small><strong>${moneyText(r.value)}</strong></div><div class="stat"><small>净利润</small><strong class="${r.profit>=0?'positive':'negative'}">${r.profit>=0?'+':''}${moneyText(r.profit)}</strong></div></div>`}${state.stage==='between'?`<div class="actions">${host()?'<button data-online-next>开始下一箱</button><button class="secondary" data-online-price>修改下一箱起拍价</button>':'<p>等待房主开始下一箱。</p>'}</div>`:''}</section>`;}
 function content(){if(!state)return landing();const intro=toolbar()+pausePanel()+playerCards();if(state.stage==='lobby')return intro+`<section class="panel online-wait"><h2>朋友入场后，一起开拍。</h2><p>把房间号 <strong>${state.code}</strong> 发给朋友，让他们在主页点击「加入房间」。所有人都要填写本局昵称。</p><p>每人5000万 · ${state.settings.rounds}箱 · 起拍${moneyText(state.settings.price)}</p>${host()?`<div class="actions"><button data-online-start ${state.players.filter(p=>p.online).length<2||state.pause?'disabled':''}>开始战局</button><button class="secondary" data-online-price>修改起拍价</button></div>`:'<p>等待房主开始战局。</p>'}</section>`;
 if(state.stage==='bidding'||state.stage==='duel')return intro+`<div class="online-layout"><section class="panel">${cluesPanel()}${silhouette()}<p class="grid-hint">相邻货物合并显示；未扫描部分不透露单件尺寸。全部货物独立等概率抽取，无品质或回本保底。</p></section>${state.stage==='bidding'?bidPanel():duelPanel()}</div>`+historyPanel();
 const board=state.lot?.winnerId?`<div class="online-layout"><section class="panel">${revealBoard()}</section>${revealPanel()}</div>`:'';return intro+boxResult()+board+leaderboard()+historyPanel();}
 function historyPanel(){return `<details class="online-history"><summary>报价历史与战局记录</summary>${state.history.map(r=>`<p>第${r.round}轮：${r.bids.map(b=>esc(name(b.id))+' '+moneyText(b.amount)).join(' · ')||'无人报价'}</p>`).join('')}${state.events.slice().reverse().map(e=>`<p>${esc(e.text)}</p>`).join('')}</details>`;}
 function render(){dialogs();document.title='洲洲盲盒 · 朋友联机';document.querySelector('[data-online-open]')?.classList.add('active');const next=state?JSON.stringify({...state,serverNow:0,revision:0,lot:state.lot?{...state.lot,items:state.lot.items?.map(it=>({...it,mask:''}))}:null,rankBy}):'landing';if(next!==signature){signature=next;const wasBidFocused=document.activeElement?.id==='onlineBidAmount';document.getElementById('game').innerHTML=`<div id="onlineGame"><p id="onlineError" class="online-error" role="alert" ${error?'':'hidden'}>${esc(error)}</p>${content()}</div>`;dragging=false;if(wasBidFocused)document.getElementById('onlineBidAmount')?.focus({preventScroll:true});initMasks();}else applyMasks();showError();if(state){document.getElementById('cash').textContent=moneyText(me().available);document.getElementById('debtStatus').textContent='联机资金 · 独立存档';document.getElementById('day').textContent=state.stage==='lobby'?'等待入场':`第${state.boxNo}/${state.settings.rounds}箱`;}else{document.getElementById('debtStatus').textContent='每人5000万独立启动资金';}
 const reminderInput=document.getElementById('onlineNoReminder');if(reminderInput&&state)reminderInput.checked=state.settings.noReminder;countdown();if(state?.stage==='between'&&host()&&!state.settings.noReminder&&priceReminder!==state.code+'-'+state.boxNo){priceReminder=state.code+'-'+state.boxNo;priceDialog();}}
 window.onlineRender=()=>{signature='';render();};
 function countdown(){if(s.view!=='online'||!state)return;const now=Date.now()-clockOffset,el=document.getElementById('onlineCountdown');if(el){const seconds=state.pause?Math.ceil((state.pause.remaining||0)/1000):Math.max(0,Math.ceil((state.deadline-now)/1000));el.textContent=(state.pause?'暂停 · ':'')+seconds+'秒';}const wait=document.getElementById('onlineHostWait');if(wait&&state.pause&&!state.pause.voteReady)wait.textContent=' '+Math.max(0,Math.ceil((60000-(now-state.pause.since))/1000))+'秒后可投票。';}
 function paintMask(canvas,mask){const rect=canvas.parentElement.getBoundingClientRect(),w=Math.max(1,Math.round(rect.width)),h=Math.max(1,Math.round(rect.height));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}const ctx=canvas.getContext('2d');ctx.globalCompositeOperation='source-over';const gradient=ctx.createLinearGradient(0,0,w,h);gradient.addColorStop(0,'#8b99a4');gradient.addColorStop(1,'#50616e');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);ctx.fillStyle='#edf3f7';ctx.font='bold 20px monospace';ctx.textAlign='center';ctx.fillText('?',w/2,h/2+7);ctx.globalCompositeOperation='destination-out';for(let y=0;y<20;y++)for(let x=0;x<20;x++)if(mask[y*20+x]==='1')ctx.clearRect(x*w/20,y*h/20,w/20+.5,h/20+.5);ctx.globalCompositeOperation='source-over';}
 function applyMasks(){if(dragging)return;document.querySelectorAll('canvas[data-online-mask]').forEach(c=>{const it=state?.lot?.items?.[Number(c.dataset.onlineMask)];if(it)paintMask(c,it.mask);});}
 function initMasks(){applyMasks();document.querySelectorAll('canvas[data-online-mask]').forEach(canvas=>{const button=canvas.parentElement;if(button.disabled)return;const slot=Number(canvas.dataset.onlineMask),boxNo=state.boxNo;let pointer=null,points=[],last=null,timer=null;
 const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];};
 const flush=()=>{clearTimeout(timer);timer=null;if(points.length){const batch=points.slice(0,80);points=points.slice(79);if(points.length===1)points=[];send('scratch',{slot,boxNo,points:batch},true);}};
 canvas.addEventListener('pointerdown',e=>{if(state.pause||pointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();pointer=e.pointerId;dragging=true;last=point(e);points=[last];canvas.setPointerCapture(pointer);});
 canvas.addEventListener('pointermove',e=>{if(pointer!==e.pointerId)return;e.preventDefault();const next=point(e),ctx=canvas.getContext('2d');ctx.globalCompositeOperation='destination-out';ctx.lineWidth=Math.min(canvas.width,canvas.height)*.3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(last[0]*canvas.width,last[1]*canvas.height);ctx.lineTo(next[0]*canvas.width,next[1]*canvas.height);ctx.stroke();ctx.globalCompositeOperation='source-over';points.push(next);last=next;if(points.length>=60)flush();else if(!timer)timer=setTimeout(flush,350);});
 const stop=e=>{if(pointer!==e.pointerId)return;pointer=null;dragging=false;flush();};canvas.addEventListener('pointerup',stop);canvas.addEventListener('pointercancel',stop);canvas.addEventListener('lostpointercapture',stop);
 button.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();send('reveal_item',{slot,boxNo});}});
 });}
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-online-open'))open();else if(b.hasAttribute('data-online-create')){open();connectDialog('create');}else if(b.hasAttribute('data-online-join')){open();connectDialog('join');}else if(b.dataset.onlineClose)document.getElementById(b.dataset.onlineClose).close();else if(b.dataset.onlineResume!==undefined){saveSession(profiles()[Number(b.dataset.onlineResume)]);state=null;signature='';open();}else if(b.hasAttribute('data-online-start'))send('start');else if(b.hasAttribute('data-online-next'))send('next');else if(b.hasAttribute('data-online-price'))priceDialog();else if(b.hasAttribute('data-online-end'))confirm('end');else if(b.hasAttribute('data-online-leave'))confirm('leave');else if(b.dataset.onlineVote){if(b.dataset.onlineVote==='end')confirm('vote');else send('vote',{choice:'continue'});}else if(b.id==='onlineConfirmAction'){const kind=b.dataset.kind;document.getElementById('onlineConfirmDialog').close();if(kind==='leave'){const leaving=session;await send('leave');forgetSession(leaving);error='';render();}else send(kind==='vote'?'vote':'end',kind==='vote'?{choice:'end'}:{});}else if(b.dataset.onlineQuick){const input=document.getElementById('onlineBidAmount'),base=Math.max(state.settings.price,state.previousBids[state.myId]||0,...Object.values(state.bids)),amount=base+Number(b.dataset.onlineQuick);if(amount>me().balance){error='该快捷总报价超过你的资金，请使用自定义报价。';showError();}else{input.value=amount/10000;bidDraft.value=input.value;}}else if(b.hasAttribute('data-online-pass'))send('pass');else if(b.dataset.duelStep)send('duel_bid',{step:Number(b.dataset.duelStep)});else if(b.hasAttribute('data-duel-pass'))send('duel_pass');else if(b.hasAttribute('data-online-reveal-all'))send('reveal_all');});
 document.addEventListener('submit',async e=>{if(e.target.id==='onlineBidForm'){e.preventDefault();send('bid',{amount:Math.round(Number(document.getElementById('onlineBidAmount').value)*10000)});}else if(e.target.id==='onlinePriceForm'){e.preventDefault();const saved=await send('settings',{price:Math.round(Number(document.getElementById('onlineNextPrice').value)*10000)});if(saved)document.getElementById('onlinePriceDialog').close();}else if(e.target.id==='onlineConnectForm'){e.preventDefault();const form=e.target,kind=form.dataset.kind,button=document.getElementById('onlineConnectSubmit');button.disabled=true;document.getElementById('onlineConnectError').textContent='';try{const nick=form.elements.nickname.value.trim(),code=form.elements.code.value,stored=kind==='join'?profiles().find(p=>p.code===code&&p.nickname===nick):null;let result;if(stored){try{result=await post('rooms/'+code+'/state',{},stored.token);}catch(err){if(![401,404,410].includes(err.status))throw err;localStorage.setItem(PROFILES,JSON.stringify(profiles().filter(p=>p.code!==code||p.nickname!==nick)));if(err.status!==401)throw err;result=await post('rooms/'+code+'/join',{nickname:nick},null);}}else result=await post(kind==='create'?'rooms/create':'rooms/'+code+'/join',kind==='create'?{nickname:nick,price:Math.round(Number(form.elements.price.value)*10000),rounds:Number(form.elements.rounds.value)}:{nickname:nick},null);saveSession({code:result.state.code,token:result.token||stored?.token||session?.token,nickname:nick});state=result.state;signature='';document.getElementById('onlineConnectDialog').close();render();}catch(err){document.getElementById('onlineConnectError').textContent=err.message;}finally{button.disabled=false;}}});
 document.addEventListener('input',e=>{if(e.target.id==='onlineBidAmount')bidDraft.value=e.target.value;});
 document.addEventListener('change',e=>{if(e.target.id==='onlineNoReminder')send('settings',{noReminder:e.target.checked});else if(e.target.id==='onlineRankBy'){rankBy=e.target.value;signature='';render();}});
 window.addEventListener('pagehide',()=>{if(session)fetch(API+'/api/rooms/'+session.code+'/action',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({type:'disconnect',requestId:crypto.randomUUID()})}).catch(()=>{});});
 window.addEventListener('online',poll);setInterval(poll,1500);setInterval(countdown,200);if(s.view==='online'){render();poll();}
})();
